@@ -0,0 +1,617 @@
+// Copyright 2026 The LevelDB-Go and Pebble Authors. All rights reserved. Use
+// of this source code is governed by a BSD-style license that can be found in
+// the LICENSE file.
+
+package pebble
+
+import (
+	"context"
+	"fmt"
+	"sync"
+	"sync/atomic"
+	"time"
+
+	"github.com/cockroachdb/errors"
+	"github.com/cockroachdb/pebble/internal/base"
+)
+
+var (
+	// ErrJobExpired is returned when waiting for a job that was evicted from
+	// the bounded retention window.
+	ErrJobExpired = errors.New("pebble: job expired from retention window")
+
+	// ErrJobUnknown is returned when waiting for a job that was never seen or has ID <= 0.
+	ErrJobUnknown = errors.New("pebble: job unknown")
+
+	// ErrTooManySubscriptions is returned when the maximum number of outstanding
+	// durability subscriptions is exceeded.
+	ErrTooManySubscriptions = errors.New("pebble: too many durability subscriptions")
+)
+
+// DurabilityStats provides a snapshot of WAL durability metrics.
+type DurabilityStats struct {
+	HighestDurableSeqNum   base.SeqNum
+	FirstErr               error
+	PendingWaiters         int64
+	TotalDurableCommits    uint64
+	TotalFailedCommits     uint64
+	CumulativeSyncDuration time.Duration
+	MaxSyncDuration       time.Duration
+}
+
+const (
+	defaultJobRetentionWindow          = 4096
+	defaultMaxOutstandingSubscriptions = 4096
+)
+
+type durabilitySub struct {
+	seqNum base.SeqNum
+	ch     chan error
+}
+
+type jobState struct {
+	jobID  int
+	done   bool
+	err    error
+	doneCh chan struct{}
+}
+
+type durabilityManager struct {
+	mu sync.Mutex
+
+	batchDurableConfigured bool
+
+	// Metrics accumulated only when BatchDurable is configured.
+	durableCommitCount    atomic.Uint64
+	durableCommitDuration atomic.Int64
+
+	// Durability stats
+	highestDurableSeqNum   base.SeqNum
+	firstErr               error
+	pendingWaiters         int64
+	totalDurableCommits    uint64
+	totalFailedCommits     uint64
+	cumulativeSyncDuration time.Duration
+	maxSyncDuration        time.Duration
+
+	// Closed state
+	closed bool
+
+	// Change broadcast channel. Closed and recreated whenever durable state changes.
+	changeCh chan struct{}
+
+	// Job durability tracking
+	nextJobID              atomic.Int64
+	maxJobRetention        int
+	highestRegisteredJobID int
+	lowestRetainedJobID    int
+	jobs                   map[int]*jobState
+	completedJobsQueue     []int
+
+	// Durability subscriptions
+	maxSubscriptions int
+	subscriptions    []durabilitySub
+}
+
+func newDurabilityManager(batchDurableConfigured bool) *durabilityManager {
+	return &durabilityManager{
+		batchDurableConfigured: batchDurableConfigured,
+		changeCh:               make(chan struct{}),
+		maxJobRetention:        defaultJobRetentionWindow,
+		maxSubscriptions:       defaultMaxOutstandingSubscriptions,
+		jobs:                   make(map[int]*jobState),
+	}
+}
+
+func (m *durabilityManager) newJobID() int {
+	return int(m.nextJobID.Add(1))
+}
+
+func (m *durabilityManager) registerJob(jobID int) *jobState {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+
+	if jobID > m.highestRegisteredJobID {
+		m.highestRegisteredJobID = jobID
+	}
+	if m.lowestRetainedJobID == 0 {
+		m.lowestRetainedJobID = jobID
+	}
+	js := &jobState{
+		jobID:  jobID,
+		doneCh: make(chan struct{}),
+	}
+	m.jobs[jobID] = js
+	return js
+}
+
+func (d *DB) onBatchDurable(info BatchDurableInfo) {
+	d.durability.mu.Lock()
+
+	if info.Err != nil {
+		if d.durability.firstErr == nil {
+			d.durability.firstErr = info.Err
+		}
+		d.durability.totalFailedCommits++
+	} else {
+		d.durability.totalDurableCommits++
+		highestSeq := info.SeqNum
+		if info.KeyCount > 0 {
+			highestSeq = info.SeqNum + base.SeqNum(info.KeyCount-1)
+		}
+		if highestSeq > d.durability.highestDurableSeqNum {
+			d.durability.highestDurableSeqNum = highestSeq
+		}
+		d.durability.cumulativeSyncDuration += info.SyncDuration
+		if info.SyncDuration > d.durability.maxSyncDuration {
+			d.durability.maxSyncDuration = info.SyncDuration
+		}
+	}
+
+	// Update job state in retention window.
+	if js, ok := d.durability.jobs[info.JobID]; ok {
+		if !js.done {
+			js.done = true
+			js.err = info.Err
+			close(js.doneCh)
+			d.durability.completedJobsQueue = append(d.durability.completedJobsQueue, info.JobID)
+			for len(d.durability.completedJobsQueue) > d.durability.maxJobRetention {
+				oldID := d.durability.completedJobsQueue[0]
+				d.durability.completedJobsQueue = d.durability.completedJobsQueue[1:]
+				delete(d.durability.jobs, oldID)
+				if oldID >= d.durability.lowestRetainedJobID {
+					d.durability.lowestRetainedJobID = oldID + 1
+				}
+			}
+		}
+	}
+
+	// Deliver to subscriptions.
+	if d.durability.firstErr != nil {
+		for _, sub := range d.durability.subscriptions {
+			sub.ch <- d.durability.firstErr
+		}
+		d.durability.subscriptions = nil
+	} else {
+		remaining := d.durability.subscriptions[:0]
+		for _, sub := range d.durability.subscriptions {
+			isDurable := false
+			if sub.seqNum == 0 {
+				isDurable = d.durability.totalDurableCommits > 0
+			} else {
+				isDurable = d.durability.highestDurableSeqNum >= sub.seqNum
+			}
+			if isDurable {
+				sub.ch <- nil
+			} else {
+				remaining = append(remaining, sub)
+			}
+		}
+		d.durability.subscriptions = remaining
+	}
+
+	// Wake up blocked waiters.
+	close(d.durability.changeCh)
+	d.durability.changeCh = make(chan struct{})
+
+	// Accumulate metrics if configured and successful.
+	if d.durability.batchDurableConfigured && info.Err == nil {
+		d.durability.durableCommitCount.Add(1)
+		d.durability.durableCommitDuration.Add(int64(info.SyncDuration))
+	}
+
+	d.durability.mu.Unlock()
+
+	// Invoke EventListener callback outside durability mutex.
+	d.opts.EventListener.BatchDurable(info)
+}
+
+func (m *durabilityManager) onClose(err error) {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+
+	if m.closed {
+		return
+	}
+	m.closed = true
+
+	// Mark all in-flight jobs as done with error.
+	for _, js := range m.jobs {
+		if !js.done {
+			js.done = true
+			js.err = err
+			close(js.doneCh)
+		}
+	}
+
+	// Deliver error to all subscriptions.
+	for _, sub := range m.subscriptions {
+		sub.ch <- err
+	}
+	m.subscriptions = nil
+
+	// Wake up all waiters.
+	close(m.changeCh)
+	m.changeCh = make(chan struct{})
+}
+
+func (m *durabilityManager) waitForDurability(ctx context.Context, seqNum base.SeqNum) error {
+	m.mu.Lock()
+	for {
+		if m.closed {
+			m.mu.Unlock()
+			return ErrClosed
+		}
+		if m.firstErr != nil {
+			err := m.firstErr
+			m.mu.Unlock()
+			return err
+		}
+		isDurable := false
+		if seqNum == 0 {
+			isDurable = m.totalDurableCommits > 0
+		} else {
+			isDurable = m.highestDurableSeqNum >= seqNum
+		}
+		if isDurable {
+			m.mu.Unlock()
+			return nil
+		}
+
+		if ctx != nil && ctx.Err() != nil {
+			m.mu.Unlock()
+			return ctx.Err()
+		}
+
+		ch := m.changeCh
+		m.pendingWaiters++
+		m.mu.Unlock()
+
+		if ctx == nil {
+			<-ch
+			m.mu.Lock()
+			m.pendingWaiters--
+			continue
+		}
+
+		select {
+		case <-ch:
+			m.mu.Lock()
+			m.pendingWaiters--
+			continue
+		case <-ctx.Done():
+			m.mu.Lock()
+			m.pendingWaiters--
+			// Precedence check: durability/close errors take precedence over context cancellation.
+			if m.closed {
+				m.mu.Unlock()
+				return ErrClosed
+			}
+			if m.firstErr != nil {
+				err := m.firstErr
+				m.mu.Unlock()
+				return err
+			}
+			if (seqNum == 0 && m.totalDurableCommits > 0) ||
+				(seqNum > 0 && m.highestDurableSeqNum >= seqNum) {
+				m.mu.Unlock()
+				return nil
+			}
+			m.mu.Unlock()
+			return ctx.Err()
+		}
+	}
+}
+
+func (m *durabilityManager) waitForDurabilityBatch(ctx context.Context, seqNums []base.SeqNum) error {
+	if len(seqNums) == 0 {
+		return nil
+	}
+
+	m.mu.Lock()
+
+	allDurableLocked := func() bool {
+		for _, s := range seqNums {
+			if s == 0 {
+				if m.totalDurableCommits == 0 {
+					return false
+				}
+			} else {
+				if m.highestDurableSeqNum < s {
+					return false
+				}
+			}
+		}
+		return true
+	}
+
+	for {
+		if m.closed {
+			m.mu.Unlock()
+			return ErrClosed
+		}
+		if m.firstErr != nil {
+			err := m.firstErr
+			m.mu.Unlock()
+			return err
+		}
+		if allDurableLocked() {
+			m.mu.Unlock()
+			return nil
+		}
+
+		if ctx != nil && ctx.Err() != nil {
+			m.mu.Unlock()
+			return ctx.Err()
+		}
+
+		ch := m.changeCh
+		m.pendingWaiters++
+		m.mu.Unlock()
+
+		if ctx == nil {
+			<-ch
+			m.mu.Lock()
+			m.pendingWaiters--
+			continue
+		}
+
+		select {
+		case <-ch:
+			m.mu.Lock()
+			m.pendingWaiters--
+			continue
+		case <-ctx.Done():
+			m.mu.Lock()
+			m.pendingWaiters--
+			// Precedence check: durability/close errors take precedence over context cancellation.
+			if m.closed {
+				m.mu.Unlock()
+				return ErrClosed
+			}
+			if m.firstErr != nil {
+				err := m.firstErr
+				m.mu.Unlock()
+				return err
+			}
+			if allDurableLocked() {
+				m.mu.Unlock()
+				return nil
+			}
+			m.mu.Unlock()
+			return ctx.Err()
+		}
+	}
+}
+
+func (m *durabilityManager) waitForJobDurability(ctx context.Context, jobID int) error {
+	if jobID <= 0 {
+		return fmt.Errorf("%w: job %d <= 0", ErrJobUnknown, jobID)
+	}
+
+	m.mu.Lock()
+
+	if jobID > m.highestRegisteredJobID {
+		m.mu.Unlock()
+		return fmt.Errorf("%w: job %d never seen", ErrJobUnknown, jobID)
+	}
+	js, ok := m.jobs[jobID]
+	if !ok {
+		m.mu.Unlock()
+		return fmt.Errorf("%w: job %d expired from retention window", ErrJobExpired, jobID)
+	}
+	if js.done {
+		err := js.err
+		m.mu.Unlock()
+		return err
+	}
+	if m.closed {
+		m.mu.Unlock()
+		return ErrClosed
+	}
+	if m.firstErr != nil {
+		err := m.firstErr
+		m.mu.Unlock()
+		return err
+	}
+
+	if ctx != nil && ctx.Err() != nil {
+		m.mu.Unlock()
+		return ctx.Err()
+	}
+
+	doneCh := js.doneCh
+	m.pendingWaiters++
+	m.mu.Unlock()
+
+	if ctx == nil {
+		<-doneCh
+		m.mu.Lock()
+		m.pendingWaiters--
+		err := js.err
+		closed := m.closed
+		firstErr := m.firstErr
+		m.mu.Unlock()
+		if closed && !js.done {
+			return ErrClosed
+		}
+		if firstErr != nil && !js.done {
+			return firstErr
+		}
+		return err
+	}
+
+	select {
+	case <-doneCh:
+		m.mu.Lock()
+		m.pendingWaiters--
+		err := js.err
+		closed := m.closed
+		firstErr := m.firstErr
+		m.mu.Unlock()
+		if closed && !js.done {
+			return ErrClosed
+		}
+		if firstErr != nil && !js.done {
+			return firstErr
+		}
+		return err
+
+	case <-ctx.Done():
+		m.mu.Lock()
+		m.pendingWaiters--
+		// Precedence check: durability/close errors take precedence over context cancellation.
+		if js.done {
+			err := js.err
+			m.mu.Unlock()
+			return err
+		}
+		if m.closed {
+			m.mu.Unlock()
+			return ErrClosed
+		}
+		if m.firstErr != nil {
+			err := m.firstErr
+			m.mu.Unlock()
+			return err
+		}
+		m.mu.Unlock()
+		return ctx.Err()
+	}
+}
+
+func (m *durabilityManager) durableState() (base.SeqNum, error) {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+	return m.highestDurableSeqNum, m.firstErr
+}
+
+func (m *durabilityManager) durabilityNotify(seqNum base.SeqNum) <-chan error {
+	ch := make(chan error, 1)
+
+	m.mu.Lock()
+	defer m.mu.Unlock()
+
+	if m.closed {
+		ch <- ErrClosed
+		return ch
+	}
+	if m.firstErr != nil {
+		ch <- m.firstErr
+		return ch
+	}
+	isDurable := false
+	if seqNum == 0 {
+		isDurable = m.totalDurableCommits > 0
+	} else {
+		isDurable = m.highestDurableSeqNum >= seqNum
+	}
+	if isDurable {
+		ch <- nil
+		return ch
+	}
+	if len(m.subscriptions) >= m.maxSubscriptions {
+		ch <- ErrTooManySubscriptions
+		return ch
+	}
+
+	m.subscriptions = append(m.subscriptions, durabilitySub{
+		seqNum: seqNum,
+		ch:     ch,
+	})
+	return ch
+}
+
+func (m *durabilityManager) durabilityStats() DurabilityStats {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+	return DurabilityStats{
+		HighestDurableSeqNum:   m.highestDurableSeqNum,
+		FirstErr:               m.firstErr,
+		PendingWaiters:         m.pendingWaiters,
